var DST = 9;
var a, da, s, r, pal;

function setup() {
	createCanvas(windowWidth, windowHeight);
	describe("centered growing circles with dots of random colors from a palette");
	noStroke();

	r = 0;
	s = DST/2;
	pal = random(palettes);
	background(random(pal)); // background("navy");
	a = TAU + 1;

	loop();
}

function draw() {
	if (a >= TAU - 0.001) {
		a = 0;
		r += DST;
		const u = TAU * r;
		const n = ~~(u / DST);
		// da = DST / u * TAU; // good for spirals
		da = TAU / n;
	}
	const x = cos(a) * r + width/2;
	const y = sin(a) * r + height/2;
	a += da;

	if (x < 0 && y < 0) setup();

	const dst = dist(x, y, width/2, height/2);
	if (dst / (max(width, height)/2) > random()) return;
	if (x < s || y < s || x > width-s || y > height - s) return;

	fill(random(pal));
	circle(x, y, s);
}

